package com.stocksense.web;
import com.stocksense.model.Product;import com.stocksense.repo.ProductRepository;import com.stocksense.service.*;import jakarta.validation.Valid;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import org.springframework.web.server.ResponseStatusException;import java.math.BigDecimal;import java.util.*;
@RestController @RequestMapping("/api") public class InventoryController{
 private final ProductRepository repo;private final NotificationService notifications;private final PaymentService payments;
 public InventoryController(ProductRepository r,NotificationService n,PaymentService p){repo=r;notifications=n;payments=p;}
 record ProductInput(String name,String sku,BigDecimal price,int quantity,int reorderLevel){}record AlertRequest(String email){}record PaymentRequest(BigDecimal amount,String currency){}
 @GetMapping("/products") public List<Product> all(@RequestParam(required=false)String q){return repo.findAll().stream().filter(p->q==null||p.getName().toLowerCase().contains(q.toLowerCase())||p.getSku().toLowerCase().contains(q.toLowerCase())).toList();}
 @PostMapping("/products") public Product create(@Valid @RequestBody ProductInput x){if(repo.findBySku(x.sku()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"SKU already exists");return repo.save(new Product(x.name(),x.sku(),x.price(),x.quantity(),x.reorderLevel()));}
 @PutMapping("/products/{id}") public Product update(@PathVariable Long id,@Valid @RequestBody ProductInput x){var p=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));p.setName(x.name());p.setPrice(x.price());p.setQuantity(x.quantity());p.setReorderLevel(x.reorderLevel());return repo.save(p);}
 @DeleteMapping("/products/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){if(!repo.existsById(id))throw new ResponseStatusException(HttpStatus.NOT_FOUND);repo.deleteById(id);return ResponseEntity.noContent().build();}
 @GetMapping("/products/low-stock") public List<Product> lowStock(){return repo.findAll().stream().filter(p->p.getQuantity()<=p.getReorderLevel()).toList();}
 @GetMapping("/dashboard/summary") public Map<String,Object> summary(){var all=repo.findAll();return Map.of("productCount",all.size(),"units",all.stream().mapToInt(Product::getQuantity).sum(),"lowStock",all.stream().filter(p->p.getQuantity()<=p.getReorderLevel()).count(),"inventoryValue",all.stream().map(p->p.getPrice().multiply(BigDecimal.valueOf(p.getQuantity()))).reduce(BigDecimal.ZERO,BigDecimal::add));}
 @GetMapping("/products/{id}") public Product one(@PathVariable Long id){return repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 @GetMapping("/products/sku/{sku}") public Product bySku(@PathVariable String sku){return repo.findBySku(sku).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));}
 record StockChange(int quantity){}
 @PatchMapping("/products/{id}/stock") public Product adjustStock(@PathVariable Long id,@RequestBody StockChange change){if(change.quantity()<0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Quantity cannot be negative");var p=repo.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));p.setQuantity(change.quantity());return repo.save(p);}
 @PostMapping("/products/bulk") public List<Product> bulk(@RequestBody List<ProductInput> rows){if(rows.size()>250)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Maximum batch size is 250");return rows.stream().map(x->{if(repo.findBySku(x.sku()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Duplicate SKU: "+x.sku());return repo.save(new Product(x.name(),x.sku(),x.price(),x.quantity(),x.reorderLevel()));}).toList();}
 @GetMapping("/products/count") public Map<String,Long> productCount(){return Map.of("count",repo.count());}
 @GetMapping("/reports/stock-value") public Map<String,Object> stockValue(){var value=repo.findAll().stream().map(p->p.getPrice().multiply(BigDecimal.valueOf(p.getQuantity()))).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("currency","INR","inventoryValue",value);}
 @GetMapping("/reports/low-stock") public Map<String,Object> lowStockReport(){var rows=lowStock();return Map.of("count",rows.size(),"products",rows);}
 @GetMapping("/alerts/preview") public List<Map<String,Object>> alertPreview(){return lowStock().stream().map(p->Map.<String,Object>of("product",p.getName(),"sku",p.getSku(),"quantity",p.getQuantity(),"reorderLevel",p.getReorderLevel())).toList();}
 @GetMapping("/payments/configuration") public Map<String,Object> paymentConfiguration(){boolean configured=System.getenv("RAZORPAY_KEY_ID")!=null&&!System.getenv("RAZORPAY_KEY_ID").isBlank();return Map.of("provider","Razorpay","mode","test","configured",configured);}
 @PostMapping("/alerts/low-stock") public Map<String,Object> alert(@RequestBody AlertRequest r){var low=lowStock();if(low.isEmpty())return Map.of("sent",0,"message","No low-stock products");int sent=0;for(var p:low){notifications.sendLowStock(r.email(),p.getName(),p.getQuantity());sent++;}return Map.of("sent",sent,"configured",notifications.configured());}
 @PostMapping("/payments/orders") public Map<String,Object> payment(@RequestBody PaymentRequest r){try{return payments.createOrder(r.amount(),r.currency()==null?"INR":r.currency());}catch(IllegalStateException e){throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,e.getMessage());}}
 @GetMapping("/integrations/status") public Map<String,Object> integrations(){return Map.of("sendgridConfigured",notifications.configured(),"razorpayConfigured",System.getenv("RAZORPAY_KEY_ID")!=null&&!System.getenv("RAZORPAY_KEY_ID").isBlank());}
}
